 async function currentNpcs(ctx:RuntimeReadContext,worldId:string):Promise<{catalogVersion:number;npcs:CurrentTownNpc[]}>{if(worldId!=='default')absent();const c=await catalog(ctx),town=await ctx.repository(TOWN_REPOSITORY).getCatalog();if(!town)fail('life_not_enabled',503,'The compatible current town catalog is absent');const {rules:r}=await rules(ctx),npcs:CurrentTownNpc[]=[];for(const profile of c.npcProfiles){const n=await ctx.repository(LIFE_REPOSITORY).getNpc(profile.id);if(!n)fail('life_npc_unavailable',503,'The four current NPC actors are not initialized');const base=town.npcs.find(n=>n.npcId===profile.id);if(!base)fail('life_npc_unavailable',503,'The current NPC definition is absent');const neighbors=[{x:n.position.x+1,y:n.position.y},{x:n.position.x-1,y:n.position.y},{x:n.position.x,y:n.position.y+1},{x:n.position.x,y:n.position.y-1}].filter(cell=>{try{assertCell(r,cell);return true;}catch{return false;}});const activity=await publicActivity(ctx,{kind:'npc',id:n.npcId});npcs.push({...base,...(identity.readSubjectPublicId?{publicId:await identity.readSubjectPublicId(ctx,'npc',n.npcId)}:{}),position:n.position,approachCells:sameCell(n.position,base.position)?base.approachCells:neighbors,version:n.version,actorKind:'npc',motion:n.motion,motionVersion:n.motion?Number(n.motion.segmentId.slice(n.motion.segmentId.lastIndexOf(':')+1)):null,activity,providerPresent:!!activity&&activity.actionId==='npc.duty'&&sameCell(n.position,base.position),nextCheckAt:n.nextDecisionAt});}return {catalogVersion:town.version,npcs};}
 async function readNpcIdentity(ctx:RuntimeReadContext,id:string){const c=await catalog(ctx),n=c.npcProfiles.find(n=>n.id===id);return n?{name:n.name}:null;}
 const legacyRest={lockActor:worldActivity.lockActor,async assertAvailable(ctx:RuntimeReadContext,id:string){const a=await ctx.repository(LIFE_REPOSITORY).getActor({kind:'agent',id});if(a?.body||a?.activePlanId)fail('body_occupied',409,'Finish or cancel the current life activity before a town service');},async start(ctx:RuntimeTransaction,p:Principal,op:TownOperation){if(p.kind!=='agent')absent();const q=await qualification(ctx,{kind:'agent',id:p.agentId},'life.activities.start',null,p);return startActivity(ctx,{kind:'agent',id:p.agentId},{actionId:'rest.voucher',placeId:'stone_inn',legacyOperationId:op.id},q);},async validate(ctx:RuntimeReadContext,op:TownOperation){const c=await catalog(ctx);if(op.catalogVersion<3||op.startedAt<c.activatedAt)return;const v=await ctx.repository(LIFE_REPOSITORY).getActivity('legacy-rest:'+op.id);if(!v||!['active','completed'].includes(v.state))fail('legacy_rest_source_unavailable',503,'The new rest source is unavailable');await qualification(ctx,{kind:'agent',id:op.agentId},'life.activities.start',v.qualification);},async finish(ctx:RuntimeTransaction,op:TownOperation,completed:boolean,code:string){const v=await ctx.repository(LIFE_REPOSITORY).getActivity('legacy-rest:'+op.id);if(!v)return;return settle(ctx,v,completed?'complete':code==='rule_retry_exhausted'?'interrupt':'cancel',code);},async owns(ctx:RuntimeReadContext,op:TownOperation){return !!await ctx.repository(LIFE_REPOSITORY).getActivity('legacy-rest:'+op.id);}};
 return {legacyRest,execute,query,authorizeReceipt,handleTask:tick,reconcile,worldActivity,activityView,planView,canObserveBehavior,describeBehavior,readNpcIdentity,publicActivity,currentNpcs};
